"""Read-only inventory of exact closed-job originals; no archive copies/refunds."""
import hashlib
import os
from pathlib import Path
import stat

from rlflow.store import atomic, canonical, sha
from tools.r6_budget import observe
from tools.r6_job_handoff import close_terminal_job, read, exact_job, cleanup_evidence, TERMINAL
from tools.r6_recovery import RecoveryError, checked, file_pin

DISK = 'output_actual_plus_unreleased_reservations_bytes'
MAX_FILES = 100000
MAX_MANIFEST_BYTES = 64 * 1024**2


def signature(s):
    return (s.st_dev, s.st_ino, s.st_mode, s.st_size, s.st_mtime_ns, s.st_ctime_ns)


def inventory(roots):
    """Hash all regular files, checking directory/file stability and special files.

    Hard links count once per pathname conservatively. Missing roots are explicit,
    never silently presented as complete evidence. Roots must not overlap.
    """
    resolved = {}
    for name, root in roots.items():
        root = Path(root)
        if not root.is_absolute() or root.is_symlink():
            raise RecoveryError('INVENTORY_ROOT_PATH')
        if root.resolve() != root:
            raise RecoveryError('INVENTORY_ROOT_ALIAS')
        resolved[name] = root
    paths = list(resolved.values())
    if any(a == b or a in b.parents or b in a.parents for i,a in enumerate(paths) for b in paths[i+1:]):
        raise RecoveryError('INVENTORY_ROOT_OVERLAP')
    files = []; directories = []; checked_files = []; missing = []
    for name, root in sorted(resolved.items()):
        if not root.exists():
            missing.append(name)
            continue
        stack = [root]
        while stack:
            directory = stack.pop(); before = directory.lstat()
            if not stat.S_ISDIR(before.st_mode):
                raise RecoveryError('INVENTORY_DIRECTORY_TYPE')
            directories.append((directory, signature(before)))
            for path in sorted(directory.iterdir()):
                info = path.lstat()
                if stat.S_ISDIR(info.st_mode):
                    stack.append(path)
                elif stat.S_ISREG(info.st_mode):
                    if len(files) >= MAX_FILES:
                        raise RecoveryError('INVENTORY_FILE_COUNT_BOUND')
                    digest = hashlib.sha256()
                    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
                    with os.fdopen(fd, 'rb') as stream:
                        opened = os.fstat(stream.fileno())
                        if signature(opened) != signature(info):
                            raise RecoveryError('INVENTORY_FILE_CHANGED')
                        for block in iter(lambda: stream.read(1024**2), b''):
                            digest.update(block)
                        if signature(os.fstat(stream.fileno())) != signature(info):
                            raise RecoveryError('INVENTORY_FILE_CHANGED')
                    checked_files.append((path, signature(info)))
                    files.append(dict(category=name, relative=str(path.relative_to(root)),
                        path=str(path), bytes=info.st_size, sha256=digest.hexdigest()))
                else:
                    raise RecoveryError('INVENTORY_SYMLINK_OR_SPECIAL_FILE')
                # Covers replacement/deletion after reading, not just changes to
                # an open inode that was unlinked while being hashed.
                if signature(path.lstat()) != signature(info):
                    raise RecoveryError('INVENTORY_FILE_CHANGED')
    for path, before in checked_files:
        if signature(path.lstat()) != before:
            raise RecoveryError('INVENTORY_FILE_CHANGED')
    for directory, before in directories:
        if signature(directory.lstat()) != before:
            raise RecoveryError('INVENTORY_DIRECTORY_CHANGED')
    if any(resolved[name].exists() for name in missing):
        raise RecoveryError('INVENTORY_MISSING_ROOT_APPEARED')
    files.sort(key=lambda row:(row['category'],row['relative']))
    return dict(roots={k:str(v) for k,v in resolved.items()},files=files,missing_roots=missing,
        total_original_bytes=sum(row['bytes'] for row in files),
        total_archive_copy_bytes=0,hardlink_accounting='Each pathname charged; no deduplication refund')


def record_inventory(journal, key, store):
    """Attach exact output observations atomically to the closed-job journal."""
    journal.require_writer()
    state = journal.read(); entry = state['events'][key]
    if state.get('current_job') not in (None, entry['identity']['job_id']):
        raise RecoveryError('OTHER_JOB_HANDOFF_ACTIVE')
    if entry.get('inventory'):
        # Rechecking originals must not rewind a later analysis/decision phase,
        # including when drift is detected part way through the verification.
        entry = journal.canonical_job(key,state=state)
        closure = read(checked(entry['closure']))
        spec = read(checked(entry['request']['spec']))
        job = exact_job(store.replay(),entry,spec)
        if job['status'] not in TERMINAL:raise RecoveryError('JOB_NOT_TERMINAL')
        pins,receipt = cleanup_evidence(store.root/'jobs'/job['id'],job)
        expected = dict(event_key=key,request_sha256=sha(entry['request']),job_id=job['id'],
            spec_sha256=sha(spec),evidence=pins,native_status=receipt['status'],
            native_exit_code=receipt.get('exit_code'),reservation_retained=entry['resources'],
            h1_evidence=job.get('h1_evidence'),scientific_acceptance=False)
        if (entry['identity']['input_sha256']!=sha(entry['request'])
                or any(closure.get(k)!=v for k,v in expected.items())):
            raise RecoveryError('JOB_CLOSURE_DRIFT')
    else:
        closure = close_terminal_job(journal, key, store)
    state = journal.read(); entry = state['events'][key]
    spec = read(checked(entry['request']['spec']))
    attempt = Path(spec['h1']['attempt'])
    # The exact submitted spec owns this attempt. Do not accept caller-selected
    # roots that could omit failed outputs or scan unrelated historical runs.
    expected_parent = store.root.resolve()/'attempts'
    if attempt.parent != expected_parent or not attempt.name or attempt.is_symlink():
        raise RecoveryError('INVENTORY_EXACT_ATTEMPT_ROOT')
    value = inventory({'job':store.root.resolve()/'jobs'/closure['job_id'], 'attempt':attempt})
    result = dict(schema_version='r6-job-inventory/1',event_key=key,job_id=closure['job_id'],
        closure=entry['closure'],spec=entry['request']['spec'],**value,
        output_inventory_complete=not value['missing_roots'],scientific_acceptance=False,
        native_status=closure['native_status'],native_exit_code=closure['native_exit_code'],
        metadata_accounting='Original job/attempt bytes only; controller metadata uses separate reserved capacity')
    data = canonical(result)+b'\n'
    if len(data) > MAX_MANIFEST_BYTES:
        raise RecoveryError('INVENTORY_MANIFEST_BOUND')
    path = journal.directory/'jobs'/key/'inventory.json'
    if entry.get('inventory'):
        if read(checked(entry['inventory'])) != result:
            raise RecoveryError('INVENTORY_REPLAY_DRIFT')
        return result
    elif path.exists():
        if read(path) != result:
            raise RecoveryError('INVENTORY_REPLAY_DRIFT')
    else:
        atomic(path,data)
    pin = file_pin(path)
    state['budget'] = observe(state['budget'],event_key=entry['identity'],
        resources={DISK:result['total_original_bytes']},evidence=pin)
    entry['inventory'] = pin
    violations = list(closure['budget_violations'])
    if result['total_original_bytes'] > entry['resources'].get(DISK, 0):
        violations.append('RESERVATION_EXCEEDED_'+DISK)
    entry['inventory_violations'] = violations
    if state['budget'].get('observed_cap_excess') or violations:
        state['status'] = 'JOB_BOUND_EXCEEDED'
    elif entry.get('stop_seen'):
        state['status'] = 'STOPPED_AFTER_OWNED_CLEANUP'
    elif entry.get('deadline_seen'):
        state['status'] = 'JOB_BOUND_EXCEEDED'
    elif not result['output_inventory_complete']:
        state['status'] = 'JOB_EVIDENCE_INCOMPLETE'
    else:
        state['status'] = 'INVENTORIED_PENDING_POSTRUN_AND_ANALYSIS'
    journal.save(state)
    return result
"""Close an already submitted exact R6 job using existing rlflow evidence.

This module cannot submit, issue permissions, refund reservations, launch a model
or accept scientific results. The batch writer waits locally and preserves native
failure facts. Resource admission and new-job dispatch remain separate gates.
"""
from pathlib import Path
import json
import math
import os
import time

from rlflow import experiments, policy
from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from tools.r6_recovery import RecoveryError, checked, file_pin
from tools.r6_budget import observe
from tools.r6_worker_processes import cleanup_verified

TERMINAL = {'FAILED', 'STOPPED', 'SUCCEEDED'}


def read(path):
    return json.loads(Path(path).read_text())


def exact_job(state, entry, spec):
    jid = 'J-' + sha({'id': spec['id'], 'spec': spec})[:16]
    if entry['identity']['job_id'] != jid:
        raise RecoveryError('JOB_EVENT_IDENTITY_MISMATCH')
    job = state['jobs'].get(jid)
    if job is None:
        raise RecoveryError('JOB_MISSING_NO_RESUBMISSION')
    if job.get('id') != jid or job.get('spec') != spec:
        raise RecoveryError('JOB_SPEC_DRIFT')
    return job


def no_model_workers(journal):
    state = journal.read()
    if state.get('current_model_event') is not None:
        raise RecoveryError('MODEL_HANDOFF_STILL_ACTIVE')
    for key, event in state['events'].items():
        if event['kind'] != 'model':
            continue
        if owns(event.get('process')):
            raise RecoveryError('MODEL_WORKER_ALIVE_DURING_JOB')
        call = journal.directory / 'calls' / key
        for filename in ('worker.json', 'child.json'):
            path = call / filename
            if path.exists() and owns(read(path).get('identity')):
                raise RecoveryError('MODEL_PROCESS_ALIVE_DURING_JOB')
        # An unconsumed dispatch can hide an as-yet-unbound child. Never infer
        # absence from a missing PID/receipt alone.
        if event.get('dispatch_claim') and not event.get('receipt'):
            raise RecoveryError('MODEL_DISPATCH_UNRESOLVED')
        if event.get('receipt'):
            receipt = read(checked(event['receipt']))
            if owns(receipt.get('process')) or owns(receipt.get('child_identity')):
                raise RecoveryError('MODEL_RECEIPT_PROCESS_ALIVE_DURING_JOB')
            cleanup = receipt.get('cleanup', {})
            if 'cleanup' not in receipt and state.get('legacy_model_reconciliation'):
                from tools.r6_legacy_model_reconciliation import validate_reconciliation
                validate_reconciliation(journal, key)
                continue
            if not cleanup_verified(cleanup):
                raise RecoveryError('MODEL_CLEANUP_UNCONFIRMED')
    return sum(e['kind'] == 'model' for e in state['events'].values())


def cleanup_evidence(directory, job):
    names = ('receipt.json', 'lifeguard-ack.json', 'descendant-cleanup.json',
             'lifeguard-ready.json', 'process-identity.json', 'descendant-ledger.json')
    if directory.is_symlink() or any((directory / name).is_symlink() for name in names):
        raise RecoveryError('JOB_EVIDENCE_SYMLINK')
    pins = {name: file_pin(directory / name) for name in names}
    records = {name: read(checked(pin)) for name, pin in pins.items()}
    receipt = records['receipt.json']
    if (receipt.get('job_id') != job['id'] or receipt.get('spec_sha256') != sha(job['spec'])
            or receipt.get('status') != job['status'] or job.get('receipt') != receipt):
        raise RecoveryError('NATIVE_RECEIPT_BINDING')
    ack = records['lifeguard-ack.json']; clean = records['descendant-cleanup.json']
    if (ack.get('owner') != job.get('identity') or not isinstance(ack.get('owner'), dict)
            or ack.get('descendant_cleanup') != clean or ack.get('no_survivors') is not True
            or clean.get('quiescent') is not True or clean.get('timed_out') is not False
            or clean.get('survivors') != []
            or type(clean.get('stable_scans')) is not int
            or type(clean.get('required_stable_scans')) is not int
            or clean['stable_scans'] < max(2, clean['required_stable_scans'])):
        raise RecoveryError('NORMAL_ACK_REQUIRED')
    if records['descendant-ledger.json'].get('owner') != job['identity']:
        raise RecoveryError('DESCENDANT_LEDGER_OWNER')
    identities = [job['identity'], records['lifeguard-ready.json']['identity'],
                  records['process-identity.json'], *clean['discovered'],
                  *records['descendant-ledger.json']['descendants']]
    if any(owns(i) for i in identities):
        raise RecoveryError('OWNED_PROCESS_STILL_ALIVE')
    # Re-read after the liveness scan; never bind evidence that changed mid-check.
    for pin in pins.values():
        checked(pin)
    return pins, receipt


def close_terminal_job(journal, key, store):
    """Idempotent CPU close record, not a resource refund or scientific verdict."""
    journal.require_writer()
    state = journal.read(); entry = journal.canonical_job(key,state=state)
    if entry['kind'] != 'job' or entry['identity']['input_sha256'] != sha(entry['request']):
        raise RecoveryError('JOB_EVENT_REQUIRED')
    spec = read(checked(entry['request']['spec']))
    job = exact_job(store.replay(), entry, spec)
    if job['status'] not in TERMINAL:
        raise RecoveryError('JOB_NOT_TERMINAL')
    pins, receipt = cleanup_evidence(store.root / 'jobs' / job['id'], job)
    violations = []
    observations = {}
    for field, resource in (('elapsed_seconds', 'live_wall_seconds'), ('allocated_seconds', 'allocated_gpu_seconds')):
        value = receipt.get(field)
        if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
            violations.append('UNKNOWN_OR_INVALID_' + field)
        else:
            observations[resource] = value
            if value > entry['resources'].get(resource, -1):
                violations.append('RESERVATION_EXCEEDED_' + resource)
    result = dict(schema_version='r6-job-close/1', event_key=key,
        request_sha256=sha(entry['request']), job_id=job['id'], spec_sha256=sha(spec),
        native_status=receipt['status'], native_exit_code=receipt.get('exit_code'),
        evidence=pins, observed=observations, h1_evidence=job.get('h1_evidence'),
        reservation_retained=entry['resources'], budget_violations=violations,
        scientific_acceptance=False, output_inventory_complete=False,
        postrun_complete=False, status='CLOSED_REQUIRES_CPU_ANALYSIS_AND_POSTRUN')
    path = journal.directory / 'jobs' / key / 'close.json'
    if entry.get('closure'):
        if read(checked(entry['closure'])) != result:
            raise RecoveryError('JOB_CLOSURE_DRIFT')
    if path.exists():
        if read(path) != result:
            raise RecoveryError('JOB_CLOSURE_DRIFT')
    else:
        atomic(path, canonical(result) + b'\n')
    entry.update(closure=file_pin(path), status='JOB_CLOSED')
    if observations:
        state['budget'] = observe(state['budget'], event_key=entry['identity'],
            resources=observations, evidence=entry['closure'])
    state.update(current_job=None, status='JOB_CLOSED_PENDING_ANALYSIS')
    journal.save(state)
    return result


def job_handoff(journal, key, store, *, poll_seconds=15):
    """Wait locally for one existing job; STOP requests only its owned cancel.

    Deadline is part of the pre-registered request, not extended on restart.
    A missing job or dead handle without a conclusive receipt is reconciled once,
    then reported as ambiguous. Neither path submits or reruns anything.
    """
    journal.require_writer()
    if type(poll_seconds) not in (int, float) or not 0 < poll_seconds <= 60:
        raise RecoveryError('LOCAL_POLL_INTERVAL')
    state = journal.read(); entry = journal.canonical_job(key,state=state); request = entry['request']
    if (entry['kind'] != 'job' or set(request) != {'spec', 'wait_deadline_unix'}
            or entry['identity']['input_sha256'] != sha(request)):
        raise RecoveryError('JOB_REQUEST_IDENTITY')
    deadline = request['wait_deadline_unix']
    if type(deadline) not in (int, float) or not math.isfinite(deadline):
        raise RecoveryError('JOB_DEADLINE')
    spec = read(checked(request['spec']))
    for resource in ('live_wall_seconds', 'allocated_gpu_seconds'):
        if entry['resources'].get(resource, -1) < spec['resources']['wall_seconds'] + 180:
            raise RecoveryError('JOB_CLEANUP_RESERVATION_REQUIRED')
    if deadline > time.time() + spec['resources']['wall_seconds']:
        raise RecoveryError('JOB_DEADLINE_EXCEEDS_BOUND')
    job = exact_job(store.replay(), entry, spec)
    if state.get('current_job') not in (None, job['id']):
        raise RecoveryError('OTHER_JOB_HANDOFF_ACTIVE')
    model_count = no_model_workers(journal)
    directory = store.root / 'jobs' / job['id']
    state.update(current_job=job['id'], controller_identity=identity(os.getpid()), status='WAIT_EXACT_JOB')
    journal.save(state)
    while True:
        if no_model_workers(journal) != model_count:
            raise RecoveryError('NEW_MODEL_EVENT_DURING_JOB_WAIT')
        store_state = store.replay()
        job = exact_job(store_state, journal.read()['events'][key], spec)
        state = journal.read(); entry = journal.canonical_job(key,state=state)
        root = Path(__file__).resolve().parents[1]
        extra_stops = [journal.directory.parent/'STOP', root/'STOP',
            root/'coordination/STOP', root/'coordination/commander/STOP', root/'coordination/executor/STOP']
        stop = bool(journal.stopped() or policy.stopped(store.root)
            or any(p.exists() for p in extra_stops) or store_state.get('paused'))
        expired = time.time() >= deadline
        if stop or expired:
            entry['stop_seen'] = bool(entry.get('stop_seen') or stop)
            entry['deadline_seen'] = bool(entry.get('deadline_seen') or expired)
            journal.save(state)
            if job['status'] not in TERMINAL:
                if entry.get('cancel_claim'):
                    if not (directory / 'cancel').exists():
                        raise RecoveryError('CANCEL_AMBIGUOUS_NO_RETRY')
                else:
                    entry['cancel_claim'] = dict(job_id=job['id'], identity=job.get('identity'))
                    journal.save(state)
                    experiments.cancel(store, job['id'])
        if (directory / 'receipt.json').exists() or not owns(job.get('identity')):
            experiments.reconcile(store, job['id'])
            job = exact_job(store.replay(), journal.read()['events'][key], spec)
        if job['status'] in TERMINAL:
            result = close_terminal_job(journal, key, store)
            state = journal.read(); entry = journal.canonical_job(key,state=state)
            state['current_job'] = None
            state['status'] = ('STOPPED_AFTER_OWNED_CLEANUP' if entry.get('stop_seen')
                else 'JOB_BOUND_EXCEEDED' if entry.get('deadline_seen') or result['budget_violations']
                else 'CPU_ANALYZE')
            journal.save(state)
            return result
        if not owns(job.get('identity')):
            raise RecoveryError('JOB_HANDLE_MISSING_NO_RETRY')
        if time.time() >= deadline + 180:
            raise RecoveryError('OWNED_CLEANUP_TIMEOUT')
        state = journal.read(); entry = journal.canonical_job(key,state=state)
        entry['local_wait_observations'] = entry.get('local_wait_observations', 0) + 1
        entry['last_local_wait'] = dict(time=time.time(), job_id=job['id'], process=job['identity'],
            model_events=model_count, model_workers_present=False)
        journal.save(state)
        time.sleep(poll_seconds)

"""Two fixed R6 postrun queries with durable intent/receipt; never a live launcher."""
import argparse
import json
import math
import os
from pathlib import Path
import selectors
import signal
import subprocess
import sys
import time

from rlflow import policy
from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from tools.r6_recovery import Journal, RecoveryError, checked, file_pin
from tools.r6_worker_processes import become_subreaper, cleanup
from tools.r6_model_worker import output_size, write
from tools.r6_budget import admissible

ROOT = Path(__file__).resolve().parents[1]
QUERIES = ('--query-gpu=index,name,driver_version,memory.total,memory.used,utilization.gpu',
           '--query-compute-apps=pid,process_name,used_gpu_memory')
CAP = 1024**2


def validate(journal, key):
    state = journal.read(); entry = state['events'][key]; request = entry['request']
    if (entry['kind'] != 'postrun' or sha(entry['identity']) != key
            or entry['identity']['input_sha256'] != sha(request)
            or set(request) != {'job_event_key','closure','inventory','executable','ordinal'}
            or type(request['ordinal']) is not int or request['ordinal'] not in (0,1)):
        raise RecoveryError('POSTRUN_REQUEST_IDENTITY')
    expected_event = 'POSTRUN:'+request['job_event_key']+':'+str(request['ordinal'])
    if (entry['identity']['event_id'] != expected_event or entry['identity']['role'] != 'postrun'
            or entry['identity']['goal_id'] != state['goal_id']):
        raise RecoveryError('POSTRUN_CANONICAL_EVENT')
    matching = [e for e in state['events'].values() if e['kind'] == 'postrun'
        and e['identity']['job_id'] == entry['identity']['job_id']
        and e['request'].get('ordinal') == request['ordinal']]
    if len(matching) != 1:raise RecoveryError('POSTRUN_DUPLICATE_ORDINAL')
    job = journal.canonical_job(request['job_event_key'],state=state)
    if (job['kind'] != 'job' or job.get('closure') != request['closure']
            or job.get('inventory') != request['inventory']
            or job['identity']['job_id'] != entry['identity']['job_id']):
        raise RecoveryError('POSTRUN_JOB_BINDING')
    close = json.loads(checked(request['closure']).read_text())
    inv = json.loads(checked(request['inventory']).read_text())
    if (close['job_id'] != entry['identity']['job_id'] or close['event_key'] != request['job_event_key']
            or inv['job_id'] != close['job_id'] or inv['closure'] != request['closure']):
        raise RecoveryError('POSTRUN_CLOSURE_IDENTITY')
    for pin in close['evidence'].values():checked(pin)
    if entry['resources'].get('output_actual_plus_unreleased_reservations_bytes',0) < CAP+65536:
        raise RecoveryError('POSTRUN_OUTPUT_RESERVATION')
    spec = json.loads(checked(job['request']['spec']).read_text())
    executable = checked(request['executable'])
    if spec['backend'] == 'real':
        if state['budget']['capacity_pass'] is not True:
            raise RecoveryError('POSTRUN_REAL_CAPACITY_REQUIRED')
        from training_workloads.unified_h1.config import resource_binding_pins
        pins = resource_binding_pins()
        if request['executable'] != {'path':pins['nvidia_smi_path'],'sha256':pins['nvidia_smi_sha256']}:
            raise RecoveryError('POSTRUN_FROZEN_EXECUTABLE')
    elif (spec['backend'] != 'runner_cpu' or state['goal_id'] != 'R6-CPU-TEST-FIXTURE'
            or not executable.is_relative_to(journal.directory.parent.resolve())):
        raise RecoveryError('POSTRUN_CPU_FIXTURE_BOUNDARY')
    return entry, executable


def stop_paths(journal):
    return journal.stopped() + policy.stopped(ROOT/'coordination/research') + [str(p) for p in
        (journal.directory.parent/'STOP',ROOT/'STOP',ROOT/'coordination/STOP',
         ROOT/'coordination/commander/STOP',ROOT/'coordination/executor/STOP') if p.exists()]


def run_query(journal, key):
    """Separate bounded worker persists its identity before the query side effect."""
    entry, executable = validate(journal,key); request = entry['request']
    admissible(journal.read()['budget'])
    if not entry.get('dispatch_claim') or checked(entry['dispatch_claim']['worker']) != Path(__file__).resolve():
        raise RecoveryError('POSTRUN_DISPATCH_CLAIM_REQUIRED')
    directory = journal.directory/'postrun'/key;directory.mkdir(parents=True,exist_ok=True)
    if any(directory.iterdir()):raise RecoveryError('POSTRUN_EXISTING_WORKER_NO_RETRY')
    fd = os.open(directory/'ONCE',os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
    try:os.write(fd,b'one postrun query\n');os.fsync(fd)
    finally:os.close(fd)
    worker = identity(os.getpid())
    write(directory/'worker.json',{'identity':worker,'event_key':key},CAP-65536)
    argv = [str(executable),QUERIES[request['ordinal']],'--format=csv,noheader,nounits']
    write(directory/'request.json',{'request':request,'argv':argv},CAP-65536)
    proc = None; child = None; error = None; code = -1; cleaned = None
    start = time.monotonic(); interrupted = []
    previous = {s:signal.signal(s,lambda signum,frame:interrupted.append(signum)) for s in (signal.SIGTERM,signal.SIGINT)}
    try:
        if stop_paths(journal):raise RecoveryError('STOP_BEFORE_POSTRUN')
        become_subreaper()
        with (directory/'stdout').open('xb') as stdout,(directory/'stderr').open('xb') as stderr,selectors.DefaultSelector() as selector:
            proc = subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                start_new_session=True,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES=''))
            child = identity(proc.pid)
            if child is None:raise RecoveryError('POSTRUN_CHILD_EXIT_BEFORE_IDENTITY')
            write(directory/'child.json',{'identity':child,'event_key':key},CAP-65536)
            selector.register(proc.stdout,selectors.EVENT_READ,stdout)
            selector.register(proc.stderr,selectors.EVENT_READ,stderr)
            while selector.get_map() or proc.poll() is None:
                if interrupted or stop_paths(journal):raise RecoveryError('STOP_DURING_POSTRUN')
                if time.monotonic()-start > 15:raise RecoveryError('POSTRUN_TIMEOUT')
                for ready,_ in selector.select(.1):
                    data = os.read(ready.fileobj.fileno(),65536)
                    if not data:
                        selector.unregister(ready.fileobj);ready.fileobj.close();continue
                    if output_size(directory)+len(data) > CAP-65536:
                        raise RecoveryError('POSTRUN_OUTPUT_CAP_BEFORE_WRITE')
                    ready.data.write(data);ready.data.flush()
            proc.wait();code = proc.returncode
            if code != 0:raise RecoveryError('POSTRUN_NONZERO_EXIT')
    except BaseException as exc:error = repr(exc)
    finally:
        if proc is not None:
            try:cleaned = cleanup(proc);code = proc.returncode
            except BaseException as exc:error = str(error)+'; '+repr(exc)
        for sig,handler in previous.items():signal.signal(sig,handler)
    for name in ('stdout','stderr'):
        path = directory/name
        if path.exists():
            with path.open('rb') as stream:os.fsync(stream.fileno())
    result = dict(event_key=key,request_sha256=sha(request),process=worker,child_identity=child,
        exit_code=code if type(code)is int else -1,error=error,cleanup=cleaned,ordinal=request['ordinal'],
        job_id=entry['identity']['job_id'],elapsed_seconds=time.monotonic()-start,
        stdout=file_pin(directory/'stdout') if (directory/'stdout').exists() else None,
        stderr=file_pin(directory/'stderr') if (directory/'stderr').exists() else None,
        automatic_retry=False,scientific_acceptance=False)
    write(directory/'receipt.json',result,CAP)
    return 0 if code == 0 and error is None else 1


def verified_receipt(journal,key):
    entry,_ = validate(journal,key)
    receipt = json.loads(checked(entry['receipt']).read_text())
    if (receipt.get('event_key') != key or receipt.get('request_sha256') != sha(entry['request'])
            or receipt.get('job_id') != entry['identity']['job_id']
            or receipt.get('ordinal') != entry['request']['ordinal']):
        raise RecoveryError('POSTRUN_RECEIPT_IDENTITY')
    for name in ('stdout','stderr'):
        if receipt.get(name):checked(receipt[name])
    if (receipt.get('exit_code') != 0 or receipt.get('error') is not None
            or (receipt.get('cleanup') or {}).get('status') != 'VERIFIED_NO_OWNED_DESCENDANTS'):
        raise RecoveryError('POSTRUN_FAILED_PRESERVED')
    if (owns(receipt.get('process')) or owns(receipt.get('child_identity'))
            or any(owns(i) for i in receipt['cleanup'].get('observed_identities',[]))):
        raise RecoveryError('POSTRUN_OWNED_PROCESS_ALIVE')
    return receipt


def owned_tree(roots):
    """Reuse rlflow's coherent ancestry snapshots; never admit by numeric PID alone."""
    from rlflow.lifeguard import _process_table, _ancestry_chain
    first = _process_table(); second = _process_table(); third = _process_table()
    found = {}
    for owner in roots:
        if not owner or first.get(owner['pid'],{}).get('identity') != owner:continue
        for pid in first:
            chain = _ancestry_chain(pid,owner['pid'],first)
            if (chain and all(first[p] == second.get(p) == third.get(p) for p in chain)
                    and all(owns(first[p]['identity']) for p in chain)):
                ident = first[pid]['identity']
                if ident['pid'] != os.getpid():found[(ident['pid'],ident['starttime'])] = ident
    return list(found.values())


def cancel_bounded(journal,key,reason,proc=None,*,directory_kind="postrun",status_prefix="POSTRUN"):
    """Persist owned identities before signals. Never manufacture a query receipt.

    Five seconds maximum per recovery invocation; original cancellation start is
    retained on restart so repeated recovery does not restart the TERM grace.
    Unknown ownership remains ambiguous and cannot authorize another query.
    """
    state = journal.read(); entry = state['events'][key]
    if directory_kind not in {'postrun','cpu-analysis'} or status_prefix not in {'POSTRUN','CPU_ANALYSIS'}:
        raise RecoveryError('CANCEL_DIRECTORY_KIND')
    directory = journal.directory/directory_kind/key
    cancel = entry.get('controller_cancel')
    if cancel is None:
        cancel = dict(reason=reason,boot_id=identity(os.getpid())['boot_id'],
            started_monotonic=time.monotonic(),known=[],status='CANCELLING')
        entry['controller_cancel'] = cancel;journal.save(state)
    end = time.monotonic()+5; empty = 0
    while True:
        if proc is not None:proc.poll()
        state = journal.read(); entry = state['events'][key];cancel = entry['controller_cancel']
        roots = [entry.get('process')]
        for name in ('worker.json','child.json'):
            path = directory/name
            if path.exists():
                record = json.loads(path.read_text())
                if record['event_key'] != key:raise RecoveryError('POSTRUN_CANCEL_IDENTITY')
                roots.append(record['identity'])
        roots += cancel['known']
        discovered = owned_tree(roots)
        for ident in discovered:
            if ident not in cancel['known']:cancel['known'].append(ident)
        if len(cancel['known']) > 128:raise RecoveryError('POSTRUN_CLEANUP_IDENTITY_BOUND')
        journal.save(state)  # before any kill; crash cannot discard known ownership
        elapsed = time.monotonic()-cancel['started_monotonic']
        sig = signal.SIGKILL if cancel['boot_id'] != identity(os.getpid())['boot_id'] or elapsed >= 1 else signal.SIGTERM
        for ident in cancel['known']:
            if owns(ident):
                try:os.kill(ident['pid'],sig)
                except ProcessLookupError:pass
            if proc is None or ident['pid'] != proc.pid:
                try:os.waitpid(ident['pid'],os.WNOHANG)
                except ChildProcessError:pass
        if proc is not None:proc.poll()
        live = [i for i in cancel['known'] if owns(i)]
        empty = empty+1 if not live and not discovered else 0
        if empty >= 2 or time.monotonic() >= end:
            state = journal.read();cancel = state['events'][key]['controller_cancel']
            cancel.update(status='NO_KNOWN_OWNED_SURVIVORS' if empty >= 2 else 'CLEANUP_BOUND_EXCEEDED',
                survivors=live,stable_empty_scans=empty)
            state['status'] = status_prefix+'_CANCELLED_REQUIRES_RECONCILIATION';journal.save(state)
            if live:raise RecoveryError('POSTRUN_CLEANUP_BOUND_EXCEEDED')
            return
        time.sleep(.05)


def postrun_handoff(journal,key,*,poll_seconds=1):
    """Recover one exact query. An unbound dispatch claim is never retried."""
    journal.require_writer()
    if type(poll_seconds) not in (int,float) or not 0 < poll_seconds <= 60:
        raise RecoveryError('POSTRUN_POLL_INTERVAL')
    entry,_ = validate(journal,key)
    if entry.get('receipt'):return verified_receipt(journal,key)
    directory = journal.directory/'postrun'/key;proc = None
    if not entry.get('dispatch_claim'):
        journal.require_dispatch_budget()
        if stop_paths(journal):raise RecoveryError('STOP_BEFORE_POSTRUN')
        if directory.exists() or entry.get('process') or entry['status'] != 'INTENT':
            raise RecoveryError('POSTRUN_UNCLAIMED_SIDE_EFFECT')
        # Check normal cleanup at dispatch, not just a historical boolean.
        from tools.r6_job_handoff import no_model_workers
        state = journal.read();jobentry = state['events'][entry['request']['job_event_key']]
        # The prior close record binds Store output; checking every recorded
        # identity here prevents postrun while an owned process remains alive.
        close = json.loads(checked(jobentry['closure']).read_text())
        records = {name:json.loads(checked(pin).read_text()) for name,pin in close['evidence'].items()}
        ids = [records['lifeguard-ack.json']['owner'],records['lifeguard-ready.json']['identity'],
            records['process-identity.json'],*records['descendant-ledger.json']['descendants'],
            *records['descendant-cleanup.json']['discovered']]
        if any(owns(i) for i in ids):raise RecoveryError('POSTRUN_JOB_STILL_ALIVE')
        no_model_workers(journal)
        entry['dispatch_claim'] = {'controller':identity(os.getpid()),'worker':file_pin(Path(__file__)),
            'deadline_monotonic':time.monotonic()+45,'deadline_wall':time.time()+45}
        state['events'][key] = entry;state['status'] = 'POSTRUN_QUERY';journal.save(state)
        become_subreaper()
        proc = subprocess.Popen([sys.executable,'-B','-m','tools.r6_postrun',str(journal.directory.resolve()),key],
            cwd=ROOT,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
            start_new_session=True,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',PYTHONPATH='.:tools/rlflow',CUDA_VISIBLE_DEVICES=''))
        ident = identity(proc.pid)
        if ident is not None:journal.bind_process(key,ident)
    while True:
        if proc is not None:proc.poll()
        entry = journal.read()['events'][key]
        workerpath = directory/'worker.json'
        if entry['process'] is None and workerpath.exists():
            worker = json.loads(workerpath.read_text())
            if worker['event_key'] != key:raise RecoveryError('POSTRUN_WORKER_EVENT')
            if owns(worker['identity']):journal.bind_process(key,worker['identity'])
        action = journal.observe(key,receipt_path=directory/'receipt.json')['action']
        if action == 'ACCEPT_RECEIPT':
            journal.consume(key,directory/'receipt.json')
            return verified_receipt(journal,key)
        if action == 'ALREADY_CONSUMED':return verified_receipt(journal,key)
        if action == 'RECONCILE':
            cancel_bounded(journal,key,'MISSING_WORKER_OR_RECEIPT',proc)
            raise RecoveryError('POSTRUN_AMBIGUOUS_NO_RETRY')
        if action not in ('WAIT_OWNED_WORKER','WAIT_OWNED_EXIT','CANCEL_OWNED'):
            raise RecoveryError('POSTRUN_UNEXPECTED_OBSERVATION')
        claim = entry.get('dispatch_claim',{})
        deadline = claim.get('deadline_monotonic')
        valid_deadline = (type(deadline) in (int,float) and math.isfinite(deadline)
            and claim.get('controller',{}).get('boot_id') == identity(os.getpid())['boot_id'])
        if entry.get('controller_cancel') or stop_paths(journal) or not valid_deadline or time.monotonic() >= deadline:
            cancel_bounded(journal,key,'STOP_OR_DISPATCH_DEADLINE',proc)
            raise RecoveryError('POSTRUN_CANCELLED_NO_RETRY')
        time.sleep(min(poll_seconds,max(.001,deadline-time.monotonic())))


def register_postruns(journal, job_key, executable, *, free_disk_bytes):
    """Reserve both fixed ordinals before launch; changed requests cannot rerun one."""
    journal.guard()
    state = journal.read(); job = journal.canonical_job(job_key,state=state)
    if job['kind'] != 'job' or not job.get('closure') or not job.get('inventory'):
        raise RecoveryError('POSTRUN_CLOSED_INVENTORIED_JOB_REQUIRED')
    keys = []
    for ordinal in (0,1):
        request = dict(job_event_key=job_key,closure=job['closure'],inventory=job['inventory'],
            executable=executable,ordinal=ordinal)
        for prior in journal.read()['events'].values():
            if (prior['kind'] == 'postrun' and prior['identity']['job_id'] == job['identity']['job_id']
                    and prior['request'].get('ordinal') == ordinal and prior['request'] != request):
                raise RecoveryError('POSTRUN_ORDINAL_ALREADY_BOUND')
        event = dict(goal_id=state['goal_id'],event_id='POSTRUN:'+job_key+':'+str(ordinal),
            job_id=job['identity']['job_id'],input_sha256=sha(request),role='postrun')
        key,_ = journal.intent(event,kind='postrun',request=request,
            resources={'output_actual_plus_unreleased_reservations_bytes':CAP+65536},
            purpose=job['purpose'],free_disk_bytes=free_disk_bytes)
        validate(journal,key);keys.append(key)
    return keys


def complete_postruns(journal, job_key, keys, *, poll_seconds=1):
    journal.require_writer()
    if len(keys) != 2 or len(set(keys)) != 2:raise RecoveryError('POSTRUN_TWO_EXACT_EVENTS')
    for ordinal,key in enumerate(keys):
        entry,_ = validate(journal,key)
        if entry['request']['ordinal'] != ordinal or entry['request']['job_event_key'] != job_key:
            raise RecoveryError('POSTRUN_ORDINAL_ORDER')
    for key in keys:postrun_handoff(journal,key,poll_seconds=poll_seconds)
    state = journal.read(); job = journal.canonical_job(job_key,state=state)
    result = dict(schema_version='r6-postrun-summary/1',job_event_key=job_key,job_id=job['identity']['job_id'],
        closure=job['closure'],inventory=job['inventory'],postrun_queries_used=2,
        receipts=[state['events'][key]['receipt'] for key in keys],
        postrun_complete=True,scientific_acceptance=False)
    path = journal.directory/'jobs'/job_key/'postrun-summary.json'
    if job.get('postrun'):
        if json.loads(checked(job['postrun']).read_text()) != result:raise RecoveryError('POSTRUN_SUMMARY_DRIFT')
        return result
    elif path.exists():
        if json.loads(path.read_text()) != result:raise RecoveryError('POSTRUN_SUMMARY_DRIFT')
    else:
        data = canonical(result)+b'\n'
        if len(data) > 65536:raise RecoveryError('POSTRUN_SUMMARY_CAP')
        atomic(path,data)
    job['postrun'] = file_pin(path)
    state['status'] = ('STOPPED_AFTER_OWNED_CLEANUP' if stop_paths(journal) or job.get('stop_seen')
        else 'JOB_BOUND_EXCEEDED' if job.get('deadline_seen') or job.get('inventory_violations') or state['budget'].get('observed_cap_excess')
        else 'JOB_EVIDENCE_INCOMPLETE' if not json.loads(checked(job['inventory']).read_text())['output_inventory_complete']
        else 'POSTRUN_COMPLETE_PENDING_ANALYSIS')
    journal.save(state)
    return result


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('directory',type=Path);parser.add_argument('event_key');args=parser.parse_args()
    raise SystemExit(run_query(Journal(args.directory.resolve()),args.event_key))

"""Bounded CPU replay after exact job closure. No model calls or live dispatch."""
import argparse
import json
import math
import os
from pathlib import Path
import selectors
import signal
import subprocess
import sys
import time

from rlflow.jobs import identity, owns
from rlflow.store import sha
from tools.r6_recovery import Journal, RecoveryError, checked, file_pin
from tools.r6_analysis_binding import analysis_context, record_analysis
from tools.r6_model_worker import write, output_size
from tools.r6_postrun import stop_paths, cancel_bounded
from tools.r6_worker_processes import become_subreaper, cleanup
from tools.r6_budget import admissible

ROOT=Path(__file__).resolve().parents[1]
PYTHON=Path('/home/mint/miniconda3/envs/navrl_blackwell_test/bin/python3.11')
LOG_CAP=1024**2
RESERVATION=20*1024**2
SOURCES=('tools/analyze_r6_evaluation.py','tools/r6_cpu_analysis.py',
 'tools/r6_analysis_binding.py','tools/r6_recovery.py','tools/r6_postrun.py',
 'tools/r6_worker_processes.py','tools/r6_model_worker.py',
 'training_workloads/unified_h1/robustness_analysis.py','training_workloads/unified_h1/robustness.py',
 'training_workloads/unified_h1/robustness_measurement_replay.py',
 'training_workloads/unified_h1/robustness_physics_replay.py',
 'training_workloads/unified_h1/robustness_audit.py','training_workloads/unified_h1/force_archive.py',
 'training_workloads/unified_h1/range_archive.py','isaaclab-training/instinctlab/observations/robustness.py')


def environment():
    # Explicit tensor runtime, CPU only. The controller remains in its own venv.
    return dict(os.environ,PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES='',
        PYTHONPATH='.:tools/rlflow:isaaclab-training',OMP_NUM_THREADS='2',MKL_NUM_THREADS='2')


def validate(journal,key):
    state=journal.read();entry=state['events'][key];request=entry['request']
    if (entry['kind']!='cpu' or sha(entry['identity'])!=key or entry['identity']['input_sha256']!=sha(request)
            or set(request)!={'job_event_key','spec','closure','inventory','postrun','python','program','sources','timeout_seconds'}):
        raise RecoveryError('CPU_ANALYSIS_REQUEST_IDENTITY')
    job=journal.canonical_job(request['job_event_key'],state=state)
    expected=dict(goal_id=state['goal_id'],event_id='CPU_ANALYSIS:'+request['job_event_key'],
        job_id=job['identity']['job_id'],input_sha256=sha(request),role='cpu-analysis')
    if entry['identity']!=expected:raise RecoveryError('CPU_ANALYSIS_CANONICAL_EVENT')
    matches=[e for e in state['events'].values() if e['kind']=='cpu' and e['identity']['job_id']==expected['job_id']
        and e['identity']['role']=='cpu-analysis']
    if len(matches)!=1:raise RecoveryError('CPU_ANALYSIS_ALIAS')
    if (request['spec']!=job['request']['spec'] or any(request[n]!=job.get(n) for n in ('closure','inventory','postrun'))):
        raise RecoveryError('CPU_ANALYSIS_JOB_BINDING')
    for n in ('spec','closure','inventory','postrun','python','program'):checked(request[n])
    if type(request['timeout_seconds']) is not int or not 1<=request['timeout_seconds']<=3600:
        raise RecoveryError('CPU_ANALYSIS_TIMEOUT_BOUND')
    if entry['resources']!={'output_actual_plus_unreleased_reservations_bytes':RESERVATION}:
        raise RecoveryError('CPU_ANALYSIS_RESERVATION')
    if request['sources']!=[file_pin(ROOT/p) for p in SOURCES]:raise RecoveryError('CPU_ANALYSIS_SOURCE_DRIFT')
    spec=json.loads(checked(request['spec']).read_text())
    if spec.get('backend')=='real':
        if request['python']!=file_pin(PYTHON) or request['program']!=file_pin(ROOT/SOURCES[0]):
            raise RecoveryError('CPU_ANALYSIS_EXECUTABLE')
    elif (spec.get('backend')!='runner_cpu' or state['goal_id']!='R6-CPU-TEST-FIXTURE'
            or not checked(request['program']).is_relative_to(journal.directory.parent.resolve())):
        raise RecoveryError('CPU_ANALYSIS_FIXTURE_BOUNDARY')
    auth=json.loads(checked(spec['pins']['authorization']).read_text())
    if spec['h1']['mode']!='research-r6-evaluation' or auth['mode']!=spec['h1']['mode']:
        raise RecoveryError('CPU_ANALYSIS_MODE')
    params=auth['parameters']['r6'];checked(params['protocol'])
    output=Path(spec['h1']['attempt'])/'results/research-r6-evaluation'
    directory=journal.directory/'cpu-analysis'/key
    if output.resolve()!=output or any(output==p or output in p.parents or p in output.parents for p in (directory.resolve(),)):
        raise RecoveryError('CPU_ANALYSIS_OUTPUT_SEPARATION')
    argv=[str(checked(request['python'])),'-B',str(checked(request['program'])),str(output),params['protocol']['path'],
        str(directory.resolve()/'result'),'--run-id',params['run_id'],'--seed',str(params['seed']),'--split',params['split']]
    return entry,argv


def register_analysis(journal,job_key,store,*,free_disk_bytes,python=None,program=None,timeout_seconds=3600):
    journal.guard();state=journal.read();job=journal.canonical_job(job_key,state=state)
    analysis_context(job,job_key,store)
    request=dict(job_event_key=job_key,spec=job['request']['spec'],closure=job['closure'],inventory=job['inventory'],
        postrun=job['postrun'],python=file_pin(PYTHON) if python is None else python,
        program=file_pin(ROOT/SOURCES[0]) if program is None else program,
        sources=[file_pin(ROOT/p) for p in SOURCES],timeout_seconds=timeout_seconds)
    for entry in state['events'].values():
        if (entry['kind']=='cpu' and entry['identity']['job_id']==job['identity']['job_id']
                and entry['identity']['role']=='cpu-analysis' and entry['request']!=request):
            raise RecoveryError('CPU_ANALYSIS_ALREADY_BOUND')
    event=dict(goal_id=state['goal_id'],event_id='CPU_ANALYSIS:'+job_key,job_id=job['identity']['job_id'],
        input_sha256=sha(request),role='cpu-analysis')
    key,_=journal.intent(event,kind='cpu',request=request,
        resources={'output_actual_plus_unreleased_reservations_bytes':RESERVATION},purpose=job['purpose'],free_disk_bytes=free_disk_bytes)
    validate(journal,key)
    return key


def run(journal,key):
    entry,argv=validate(journal,key);request=entry['request'];admissible(journal.read()['budget'])
    if not entry.get('dispatch_claim') or checked(entry['dispatch_claim']['worker'])!=Path(__file__).resolve():
        raise RecoveryError('CPU_ANALYSIS_DISPATCH_REQUIRED')
    directory=journal.directory/'cpu-analysis'/key;directory.mkdir(parents=True,exist_ok=False)
    worker=identity(os.getpid());write(directory/'worker.json',dict(identity=worker,event_key=key),LOG_CAP)
    write(directory/'request.json',dict(request=request,argv=argv),LOG_CAP)
    proc=None;child=None;error=None;code=-1;cleaned=None;outputs={}
    start=time.monotonic();interrupted=[]
    previous={s:signal.signal(s,lambda signum,frame:interrupted.append(signum)) for s in (signal.SIGTERM,signal.SIGINT)}
    try:
        if stop_paths(journal):raise RecoveryError('STOP_BEFORE_CPU_ANALYSIS')
        become_subreaper()
        with (directory/'stdout').open('xb') as stdout,(directory/'stderr').open('xb') as stderr,selectors.DefaultSelector() as selector:
            proc=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                start_new_session=True,cwd=ROOT,env=environment())
            child=identity(proc.pid)
            if child is None:raise RecoveryError('CPU_ANALYSIS_CHILD_EXIT_BEFORE_IDENTITY')
            write(directory/'child.json',dict(identity=child,event_key=key),LOG_CAP)
            selector.register(proc.stdout,selectors.EVENT_READ,stdout);selector.register(proc.stderr,selectors.EVENT_READ,stderr)
            while selector.get_map() or proc.poll() is None:
                if interrupted or stop_paths(journal):raise RecoveryError('STOP_DURING_CPU_ANALYSIS')
                if time.monotonic()-start>request['timeout_seconds']:raise RecoveryError('CPU_ANALYSIS_TIMEOUT')
                for ready,_ in selector.select(.1):
                    data=os.read(ready.fileobj.fileno(),65536)
                    if not data:selector.unregister(ready.fileobj);ready.fileobj.close();continue
                    if output_size(directory)+len(data)>LOG_CAP-65536:raise RecoveryError('CPU_ANALYSIS_LOG_CAP_BEFORE_WRITE')
                    ready.data.write(data);ready.data.flush()
            proc.wait();code=proc.returncode
            if code!=0:raise RecoveryError('CPU_ANALYSIS_NONZERO_EXIT')
    except BaseException as exc:error=repr(exc)
    finally:
        if proc is not None:
            try:cleaned=cleanup(proc);code=proc.returncode
            except BaseException as exc:error=str(error)+'; '+repr(exc)
        for sig,handler in previous.items():signal.signal(sig,handler)
    try:
        for name,limit in (('report.json',16*1024**2),('summary.json',48*1024)):
            path=directory/'result'/name
            if not path.is_file() or path.is_symlink() or path.stat().st_size>limit:raise RecoveryError('CPU_ANALYSIS_RESULT_MISSING_OR_BOUND')
            outputs[name]=file_pin(path)
    except BaseException as exc:error=str(error)+'; '+repr(exc)
    for name in ('stdout','stderr'):
        path=directory/name
        if path.exists():
            with path.open('rb') as stream:os.fsync(stream.fileno())
    result=dict(event_key=key,request_sha256=sha(request),process=worker,child_identity=child,
        exit_code=code if type(code)is int else -1,error=error,cleanup=cleaned,
        job_id=entry['identity']['job_id'],elapsed_seconds=time.monotonic()-start,outputs=outputs,
        stdout=file_pin(directory/'stdout') if (directory/'stdout').exists() else None,
        stderr=file_pin(directory/'stderr') if (directory/'stderr').exists() else None,
        automatic_retry=False,model_calls=0,scientific_acceptance=False)
    write(directory/'receipt.json',result,LOG_CAP)
    return 0 if code==0 and error is None else 1


def verified_receipt(journal,key):
    entry,_=validate(journal,key);r=json.loads(checked(entry['receipt']).read_text())
    if (r.get('event_key')!=key or r.get('request_sha256')!=sha(entry['request'])
            or r.get('job_id')!=entry['identity']['job_id']):raise RecoveryError('CPU_ANALYSIS_RECEIPT_IDENTITY')
    if (r.get('exit_code')!=0 or r.get('error') is not None
            or (r.get('cleanup') or {}).get('status')!='VERIFIED_NO_OWNED_DESCENDANTS'):
        raise RecoveryError('CPU_ANALYSIS_FAILED_PRESERVED')
    if any(owns(i) for i in [r.get('process'),r.get('child_identity'),*r['cleanup'].get('observed_identities',[])]):
        raise RecoveryError('CPU_ANALYSIS_PROCESS_ALIVE')
    for n in ('stdout','stderr'):checked(r[n])
    directory=journal.directory.resolve()/'cpu-analysis'/key/'result'
    for name,limit in (('report.json',16*1024**2),('summary.json',48*1024)):
        path=checked(r['outputs'][name])
        if path!=directory/name or path.stat().st_size>limit:raise RecoveryError('CPU_ANALYSIS_RESULT_BINDING')
    report=json.loads(checked(r['outputs']['report.json']).read_text())
    summary=json.loads(checked(r['outputs']['summary.json']).read_text())
    if summary!=report['summary']:raise RecoveryError('CPU_ANALYSIS_SUMMARY_DRIFT')
    return r


def handoff(journal,key,store,*,poll_seconds=1):
    journal.require_writer()
    if type(poll_seconds) not in (int,float) or not 0<poll_seconds<=60:raise RecoveryError('CPU_ANALYSIS_POLL')
    entry,_=validate(journal,key);job_key=entry['request']['job_event_key']
    state=journal.read();analysis_context(journal.canonical_job(job_key,state=state),job_key,store)
    if state.get('current_job') is not None or state.get('current_model_event') is not None:raise RecoveryError('CPU_ANALYSIS_NOT_IDLE')
    directory=journal.directory/'cpu-analysis'/key;proc=None
    if not entry.get('receipt') and not entry.get('dispatch_claim'):
        journal.require_dispatch_budget()
        if stop_paths(journal):raise RecoveryError('STOP_BEFORE_CPU_ANALYSIS')
        from tools.r6_job_handoff import no_model_workers
        no_model_workers(journal)
        for other_key,e in state['events'].items():
            if e['kind']=='cpu' and other_key!=key and ((e.get('dispatch_claim') and not e.get('receipt'))
                    or any(not c.get('receipt') for c in e.get('sample_claims',{}).values())):
                raise RecoveryError('CPU_ANALYSIS_OTHER_EVENT_UNRESOLVED')
        if directory.exists() or entry.get('process') or entry['status']!='INTENT':raise RecoveryError('CPU_ANALYSIS_UNCLAIMED_SIDE_EFFECT')
        duration=entry['request']['timeout_seconds']+30
        entry['dispatch_claim']=dict(controller=identity(os.getpid()),worker=file_pin(Path(__file__)),
            deadline_monotonic=time.monotonic()+duration,deadline_wall=time.time()+duration)
        state['events'][key]=entry;journal.save(state)
        become_subreaper()
        proc=subprocess.Popen([sys.executable,'-B','-m','tools.r6_cpu_analysis',str(journal.directory.resolve()),key],
            cwd=ROOT,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True,
            env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',PYTHONPATH='.:tools/rlflow',CUDA_VISIBLE_DEVICES=''))
        ident=identity(proc.pid)
        if ident is not None:journal.bind_process(key,ident)
    while True:
        if proc is not None:proc.poll()
        entry=journal.read()['events'][key]
        workerpath=directory/'worker.json'
        if entry['process'] is None and workerpath.exists():
            worker=json.loads(workerpath.read_text())
            if worker['event_key']!=key:raise RecoveryError('CPU_ANALYSIS_WORKER_IDENTITY')
            if owns(worker['identity']):journal.bind_process(key,worker['identity'])
        action=journal.observe(key,receipt_path=directory/'receipt.json')['action']
        if action in ('ACCEPT_RECEIPT','ALREADY_CONSUMED'):
            if action=='ACCEPT_RECEIPT':journal.consume(key,directory/'receipt.json')
            r=verified_receipt(journal,key)
            return record_analysis(journal,job_key,r['outputs']['report.json'],store)
        claim=entry.get('dispatch_claim',{});deadline=claim.get('deadline_monotonic')
        valid=type(deadline) in (int,float) and math.isfinite(deadline) and claim.get('controller',{}).get('boot_id')==identity(os.getpid())['boot_id']
        reason=('MISSING_WORKER_OR_RECEIPT' if action=='RECONCILE' else
            'STOP_OR_DISPATCH_DEADLINE' if entry.get('controller_cancel') or stop_paths(journal) or not valid or time.monotonic()>=deadline else None)
        if reason:
            cancel_bounded(journal,key,reason,proc,directory_kind='cpu-analysis',status_prefix='CPU_ANALYSIS')
            raise RecoveryError('CPU_ANALYSIS_AMBIGUOUS_NO_RETRY' if action=='RECONCILE' else 'CPU_ANALYSIS_CANCELLED_NO_RETRY')
        if action not in ('WAIT_OWNED_WORKER','WAIT_OWNED_EXIT','CANCEL_OWNED'):raise RecoveryError('CPU_ANALYSIS_OBSERVATION')
        time.sleep(min(poll_seconds,max(.001,deadline-time.monotonic())))


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('directory',type=Path);parser.add_argument('event_key')
    args=parser.parse_args();raise SystemExit(run(Journal(args.directory.resolve()),args.event_key))

"""R6 recovery journal, reusing rlflow atomic persistence and process identity.

This is not a launcher. The controller must hold this lock before calling any
mutation. An intent without authoritative completion never authorizes a retry.
"""
from contextlib import contextmanager
from pathlib import Path
import fcntl
import hashlib
import json
import os

from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from tools.r6_budget import reserve, admissible


class RecoveryError(RuntimeError):
    pass


def file_pin(path):
    path = Path(path).resolve()
    with path.open('rb') as stream:
        digest = hashlib.file_digest(stream, 'sha256').hexdigest()
    return {'path': str(path), 'sha256': digest}


def checked(pin):
    path = Path(pin['path'])
    if path.is_symlink() or file_pin(path) != pin:
        raise RecoveryError('PIN_DRIFT')
    return path


class Journal:
    def __init__(self, directory, stop_paths=()):
        self.directory = Path(directory)
        self.path = self.directory / 'state.json'
        self.stop_paths = [self.directory / 'STOP', *map(Path, stop_paths)]
        self._lock = None
        self._owner_pid = None

    @contextmanager
    def writer(self):
        if self._lock is not None:
            raise RecoveryError('NESTED_WRITER')
        self.directory.mkdir(parents=True, exist_ok=True)
        with (self.directory / 'writer.lock').open('a') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            self._lock, self._owner_pid = lock, os.getpid()
            try:
                yield self
            finally:
                self._lock = self._owner_pid = None
                fcntl.flock(lock, fcntl.LOCK_UN)

    def require_writer(self):
        if self._lock is None or self._owner_pid != os.getpid():
            raise RecoveryError('SINGLE_WRITER_REQUIRED')

    def stopped(self):
        return [str(p) for p in self.stop_paths if p.exists()]

    def guard(self):
        self.require_writer()
        if self.stopped():
            raise RecoveryError('STOP_NEW_ACTIONS')

    def read(self):
        return json.loads(self.path.read_text())

    def save(self, state):
        self.require_writer()
        atomic(self.path, canonical(state) + b'\n')

    def initialize(self, budget):
        self.guard()
        if self.path.exists():
            raise RecoveryError('USE_EXISTING_STATE')
        self.save({'schema_version': 'r6-recovery/1', 'goal_id': budget['goal_id'],
                   'controller_identity': identity(os.getpid()), 'budget': budget,
                   'events': {}, 'duplicate_events_rejected': 0,
                   'status': 'CPU_PREPARE', 'current_job': None})

    def intent(self, event, *, kind, request, resources, purpose, free_disk_bytes):
        """Persist request and reservation in one transaction before side effects.

        Returns (key, fresh). False means inspect existing work, never launch.
        Input hash covers the full request, including executable/prompt/schema.
        """
        self.guard()
        if kind not in {'job', 'model', 'settle', 'postrun', 'cpu'}:
            raise RecoveryError('UNKNOWN_EVENT_KIND')
        if event.get('input_sha256') != sha(request):
            raise RecoveryError('REQUEST_IDENTITY_MISMATCH')
        state = self.read()
        key = sha(event)
        entry = {'identity': event, 'kind': kind, 'request': request,
                 'resources': resources, 'purpose': purpose}
        if kind == 'job' and any(e['kind'] == 'job' and e['identity']['job_id'] == event['job_id'] and k != key
                for k, e in state['events'].items()):
            raise RecoveryError('JOB_ALREADY_BOUND_TO_EVENT')
        if key in state['events']:
            previous = state['events'][key]
            if any(previous[k] != v for k, v in entry.items()):
                raise RecoveryError('EVENT_REPLAY_DRIFT')
            admissible(state['budget'])
            state['duplicate_events_rejected'] += 1
            self.save(state)
            return key, False
        state['budget'] = reserve(state['budget'], event_key=event, resources=resources,
                                  purpose=purpose, free_disk_bytes=free_disk_bytes)
        state['events'][key] = {**entry, 'status': 'INTENT', 'process': None,
                                'receipt': None}
        self.save(state)
        return key, True

    def require_dispatch_budget(self):
        self.guard()
        admissible(self.read()['budget'])

    def canonical_job(self, key, *, state=None):
        state = self.read() if state is None else state
        entry = state['events'][key]
        if entry['kind'] != 'job':raise RecoveryError('JOB_EVENT_REQUIRED')
        aliases = [k for k,e in state['events'].items()
                   if e['kind'] == 'job' and e['identity']['job_id'] == entry['identity']['job_id']]
        if aliases != [key]:raise RecoveryError('JOB_EVENT_ALIAS_REQUIRES_RECONCILIATION')
        return entry

    def bind_process(self, key, process):
        self.require_writer()
        if not owns(process):
            raise RecoveryError('PROCESS_IDENTITY_NOT_LIVE')
        state = self.read()
        entry = state['events'][key]
        if entry['status'] != 'INTENT' or entry['process'] is not None:
            raise RecoveryError('PROCESS_ALREADY_BOUND')
        entry.update(process=process, status='RUNNING')
        self.save(state)

    def observe(self, key, *, receipt_path=None, exact_job=None):
        """Read-only recovery decision based on a receipt or a live exact handle.

        STOP never suppresses observation/cleanup of an existing owned job.
        A callback result must include the exact event job ID and request hash.
        A job receipt is not settlement; returned COMPLETE only closes this event.
        """
        entry = self.read()['events'][key]
        if entry['receipt']:
            checked(entry['receipt'])
            return {'action': 'ALREADY_CONSUMED', 'receipt': entry['receipt']}
        if receipt_path is not None and Path(receipt_path).exists():
            try:
                raw = Path(receipt_path).read_bytes()
                receipt = json.loads(raw)
            except (ValueError, UnicodeError):
                return {'action': 'RECONCILE', 'reason': 'PARTIAL_RECEIPT_NO_RETRY'}
            if not isinstance(receipt, dict):
                raise RecoveryError('INVALID_RECEIPT_OBJECT')
            if receipt.get('event_key') != key or receipt.get('request_sha256') != sha(entry['request']):
                raise RecoveryError('RECEIPT_IDENTITY_MISMATCH')
            if type(receipt.get('exit_code')) is not int:
                raise RecoveryError('INVALID_RECEIPT_EXIT_CODE')
            if entry['process'] is not None and receipt.get('process') != entry['process']:
                raise RecoveryError('RECEIPT_PROCESS_MISMATCH')
            if owns(entry['process']) or owns(receipt.get('process')):
                return {'action': 'WAIT_OWNED_EXIT'}
            return {'action': 'ACCEPT_RECEIPT', 'receipt': {
                'path': str(Path(receipt_path).resolve()),
                'sha256': hashlib.sha256(raw).hexdigest()}}
        if exact_job is not None:
            expected = entry['identity']
            if exact_job.get('job_id') != expected['job_id'] or exact_job.get('input_sha256') != expected['input_sha256']:
                raise RecoveryError('EXACT_JOB_IDENTITY_MISMATCH')
            if type(exact_job.get('terminal')) is not bool:
                raise RecoveryError('INVALID_JOB_TERMINAL_FLAG')
            if exact_job['terminal']:
                return {'action': 'CLOSE_AND_SETTLE', 'job_id': expected['job_id']}
            if owns(exact_job.get('process')):
                return {'action': 'CANCEL_OWNED' if self.stopped() else 'WAIT_EXACT_JOB',
                        'job_id': expected['job_id']}
            return {'action': 'RECONCILE', 'reason': 'JOB_HANDLE_MISSING_NO_RETRY'}
        if owns(entry['process']):
            return {'action': 'CANCEL_OWNED' if self.stopped() else 'WAIT_OWNED_WORKER'}
        return {'action': 'RECONCILE', 'reason': 'INTENT_WITHOUT_LIVE_HANDLE_OR_RECEIPT'}

    def consume(self, key, receipt_path):
        self.require_writer()
        observed = self.observe(key, receipt_path=receipt_path)
        if observed['action'] == 'ALREADY_CONSUMED':
            return False
        if observed['action'] != 'ACCEPT_RECEIPT':
            raise RecoveryError('RECEIPT_NOT_READY: ' + observed['action'])
        checked(observed['receipt'])
        state = self.read()
        entry = state['events'][key]
        entry.update(receipt=observed['receipt'], status='RECEIPT_RECORDED')
        # Even nonzero exits retain the full reservation. Decision/schema and
        # evidence acceptance are separate gates in the eventual controller.
        self.save(state)
        return True
"""R6 model handoff used by the local single-writer batch.

Consumes registered model events and closes already submitted jobs. No permission issuance, job
submission, budget reservation, automatic retry or scientific acceptance here.
Registered CPU analysis workers are supported; resource/live dispatch and next-plan phases remain incomplete.
"""
from pathlib import Path
import argparse
import json
import os
import subprocess
import sys
import time

from rlflow.jobs import identity, owns
from tools.r6_recovery import Journal, RecoveryError, checked, file_pin
from tools.r6_model_worker import validate_request
from tools.r6_worker_processes import cleanup_verified

ROOT=Path(__file__).resolve().parents[1]


def worker_environment():
    return dict(os.environ,PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES='',
                PYTHONPATH='.:tools/rlflow',GIT_TERMINAL_PROMPT='0')


def verified_decision(journal,key):
    """Receipt recording is separate from validating the returned decision."""
    entry=journal.read()['events'][key]
    receipt=json.loads(checked(entry['receipt']).read_text())
    if receipt.get('exit_code')!=0 or receipt.get('error') is not None or receipt.get('schema_valid') is not True:
        raise RecoveryError('MODEL_FAILED_PRESERVE_RECEIPT')
    if not cleanup_verified(receipt.get('cleanup')):
        raise RecoveryError('MODEL_CLEANUP_NOT_VERIFIED')
    for keyname in ('events','stderr','last_message'):
        checked(receipt[keyname])
    _,_,_,schema=validate_request(entry['request'])
    result=json.loads(checked(receipt['last_message']).read_text())
    import jsonschema
    jsonschema.validate(result,schema)
    return result


def model_handoff(journal,key,*,poll_seconds=15):
    """Caller holds the sole writer lock throughout the read-only review.

    Dispatch claim survives a crash before Popen; that ambiguous event is never
    retried. After Popen, worker.json permits exact reattachment even if the
    controller died before binding the PID into state. A receipt permits closing
    an already exited worker. STOP is handled by the worker and never removed.
    """
    journal.require_writer()
    if not 0<poll_seconds<=60:raise ValueError('LOCAL_POLL_INTERVAL')
    state=journal.read();entry=state['events'][key]
    if entry['kind']!='model':raise RecoveryError('MODEL_EVENT_REQUIRED')
    call=journal.directory/'calls'/key
    receipt_path=call/'receipt.json'
    process=None
    if entry['receipt']:
        return verified_decision(journal,key)
    if not entry.get('dispatch_claim'):
        if any(e['kind']=='cpu' and ((e.get('dispatch_claim') and not e.get('receipt'))
                or any(not c.get('receipt') for c in e.get('sample_claims',{}).values()))
                for e in state['events'].values()):
            raise RecoveryError('CPU_WORKER_HANDOFF_UNRESOLVED')
        journal.require_dispatch_budget()
        if entry['process'] is not None or entry['status']!='INTENT' or call.exists():
            raise RecoveryError('UNCLAIMED_SIDE_EFFECT_REQUIRES_RECONCILIATION')
        validate_request(entry['request'])
        entry['dispatch_claim']={'controller':identity(os.getpid()),'time':time.time(),
                                 'worker':file_pin(ROOT/'tools/r6_model_worker.py')}
        state.update(status='MODEL_REVIEW',current_model_event=key,controller_identity=identity(os.getpid()))
        journal.save(state)
        process=subprocess.Popen([sys.executable,'-B','-m','tools.r6_model_worker',
            str(journal.directory.resolve()),key],cwd=ROOT,env=worker_environment(),
            stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
            start_new_session=True)
        live=identity(process.pid)
        if live is not None:journal.bind_process(key,live)
    while True:
        if process is not None:process.poll() # Reap our child before checking owns().
        entry=journal.read()['events'][key]
        # Worker identity is persisted before any model side effect. The event
        # key plus exact Linux start/boot identity prevents PID-only attachment.
        worker_path=call/'worker.json'
        if entry['process'] is None and worker_path.exists():
            worker=json.loads(worker_path.read_text())
            if worker['event_key']!=key:raise RecoveryError('WORKER_EVENT_MISMATCH')
            if owns(worker['identity']):journal.bind_process(key,worker['identity'])
        action=journal.observe(key,receipt_path=receipt_path)['action']
        if action=='ACCEPT_RECEIPT':
            journal.consume(key,receipt_path)
            state=journal.read();state.update(status='MODEL_RECEIPT_RECORDED',current_model_event=None)
            journal.save(state)
            return verified_decision(journal,key)
        if action=='ALREADY_CONSUMED':return verified_decision(journal,key)
        if action=='RECONCILE':
            # A live process owned by this invocation may not have created its
            # worker.json yet; its exact Popen identity is already bound above.
            raise RecoveryError('MODEL_AMBIGUOUS_NO_RETRY')
        if action not in ('WAIT_OWNED_WORKER','WAIT_OWNED_EXIT','CANCEL_OWNED'):
            raise RecoveryError('UNEXPECTED_MODEL_OBSERVATION: '+action)
        # STOP is observed by the worker's bounded local loop, including cleanup.
        # No second model is called to ask whether the first one has finished.
        time.sleep(poll_seconds)


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('directory',type=Path);ap.add_argument('event_key')
    action=ap.add_mutually_exclusive_group()
    action.add_argument('--job-store',type=Path,help='Close an existing exact job in this rlflow Store; never submit')
    action.add_argument('--inventory-store',type=Path,help='Inventory exact closed-job originals; no GPU queries')
    action.add_argument('--postrun-keys',nargs=2,metavar=('GPU_EVENT','PROCESS_EVENT'),help='Complete two registered postrun queries for event_key job')
    action.add_argument('--decision',action='store_true',help='Recover a registered post-analysis decision and validate its proposal')
    action.add_argument('--cpu-analysis',action='store_true',help='Execute/recover a registered CPU analysis event; never call a model')
    action.add_argument('--analysis-report',type=Path,help='Bind an existing CPU motion replay report; no scientific acceptance')
    ap.add_argument('--analysis-store',type=Path,help='Exact Store for --analysis-report')
    a=ap.parse_args();journal=Journal(a.directory.resolve())
    if bool(a.analysis_report is not None or a.cpu_analysis or a.decision) != (a.analysis_store is not None):
        ap.error('--analysis-report, --cpu-analysis or --decision requires --analysis-store')
    with journal.writer():
        if a.decision:
            from rlflow.store import Store
            from tools.r6_decision import handoff
            result=handoff(journal,a.event_key,Store(a.analysis_store.resolve()))
        elif a.cpu_analysis:
            from rlflow.store import Store
            from tools.r6_cpu_analysis import handoff
            result=handoff(journal,a.event_key,Store(a.analysis_store.resolve()))
        elif a.analysis_report is not None:
            from rlflow.store import Store
            from tools.r6_analysis_binding import record_analysis
            result=record_analysis(journal,a.event_key,file_pin(a.analysis_report),Store(a.analysis_store.resolve()))
        elif a.postrun_keys is not None:
            from tools.r6_postrun import complete_postruns
            result=complete_postruns(journal,a.event_key,a.postrun_keys)
        elif a.inventory_store is not None:
            from rlflow.store import Store
            from tools.r6_job_inventory import record_inventory
            result=record_inventory(journal,a.event_key,Store(a.inventory_store.resolve()))
        elif a.job_store is None:
            result=model_handoff(journal,a.event_key)
        else:
            from rlflow.store import Store
            from tools.r6_job_handoff import job_handoff
            result=job_handoff(journal,a.event_key,Store(a.job_store.resolve()))
    print(json.dumps(result,ensure_ascii=False))


if __name__=='__main__':main()

"""Bind offline motion replay to closed-job originals without accepting science.

This consumer launches nothing. The report is an implementation-produced replay,
not an independent review or permission to dispatch another experiment.
"""
import json
from pathlib import Path

from rlflow.store import atomic, canonical, sha
from tools.r6_recovery import checked, file_pin, RecoveryError
from tools.r6_job_handoff import exact_job, cleanup_evidence, TERMINAL


def read(pin):
    return json.loads(checked(pin).read_text())


def analysis_context(entry, key, store):
    spec = read(entry['request']['spec'])
    job = exact_job(store.replay(), entry, spec)
    if job['status'] not in TERMINAL:
        raise RecoveryError('ANALYSIS_REQUIRES_TERMINAL_JOB')
    _, native = cleanup_evidence(store.root/'jobs'/job['id'], job)
    closure = read(entry['closure']); inventory = read(entry['inventory']); postrun = read(entry['postrun'])
    if (closure['event_key'] != key or closure['job_id'] != job['id'] or closure['spec_sha256'] != sha(spec)
            or closure['native_status'] != native['status'] or closure['native_exit_code'] != native.get('exit_code')
            or inventory['event_key'] != key or inventory['job_id'] != job['id']
            or inventory['spec'] != entry['request']['spec'] or inventory['closure'] != entry['closure']
            or postrun['job_event_key'] != key or postrun['job_id'] != job['id']
            or postrun['closure'] != entry['closure'] or postrun['inventory'] != entry['inventory']
            or postrun.get('postrun_complete') is not True or postrun.get('postrun_queries_used') != 2
            or len(postrun.get('receipts',[])) != 2
            or len({p['path'] for p in postrun['receipts']}) != 2):
        raise RecoveryError('ANALYSIS_JOB_CHAIN_BINDING')
    for receipt in postrun['receipts']:
        checked(receipt)
    attempt = Path(spec['h1']['attempt'])
    if (attempt.parent != store.root.resolve()/'attempts' or inventory['roots']['attempt'] != str(attempt)
            or spec['h1']['mode'] != 'research-r6-evaluation'):
        raise RecoveryError('ANALYSIS_EXACT_R6_ATTEMPT')
    output = attempt/'results/research-r6-evaluation'
    auth_pin = spec['pins']['authorization']; auth = read(auth_pin)
    argv = spec['argv']
    for flag, value in [('--authorization', auth_pin['path']), ('--attempt',str(attempt)), ('--mode','research-r6-evaluation')]:
        if argv.count(flag) != 1 or argv.index(flag)+1 >= len(argv) or argv[argv.index(flag)+1] != value:
            raise RecoveryError('ANALYSIS_AUTHORIZATION_ARGV')
    if auth['mode'] != spec['h1']['mode']:
        raise RecoveryError('ANALYSIS_AUTHORIZATION_MODE')
    parameters = auth['parameters']; request = parameters['r6']
    protocol = read(request['protocol'])
    if (protocol.get('frozen') is not True or len(protocol['blocks']) != 16
            or len(set(request['block_ids'])) != 16 or len(request['block_ids']) != 16
            or set(request['block_ids']) != {b['id'] for b in protocol['blocks']}):
        raise RecoveryError('ANALYSIS_PROTOCOL_NOT_FROZEN_OR_INCOMPLETE')
    return dict(spec=spec,job=job,closure=closure,inventory=inventory,output=output,
                auth_pin=auth_pin,parameters=parameters,request=request,protocol=protocol)


def bind_analysis(entry, key, report_pin, store):
    context=analysis_context(entry,key,store)
    spec=context['spec'];job=context['job'];closure=context['closure'];inventory=context['inventory']
    output=context['output'];auth_pin=context['auth_pin'];parameters=context['parameters']
    request=context['request'];protocol=context['protocol']
    if checked(report_pin).stat().st_size > 16*1024**2:
        raise RecoveryError('ANALYSIS_REPORT_SIZE_BOUND')
    report = read(report_pin)
    if report.get('schema_version') != 'r6-motion-replay/1' or report.get('scientific_acceptance') is not False:
        raise RecoveryError('ANALYSIS_REPORT_SCHEMA')
    for field in ('run_id','seed','split'):
        if report[field] != request[field]:
            raise RecoveryError('ANALYSIS_RUN_IDENTITY')
    if [r['block_id'] for r in report['blocks']] != [b['id'] for b in protocol['blocks']]:
        raise RecoveryError('ANALYSIS_BLOCK_COVERAGE')
    from training_workloads.unified_h1 import robustness_analysis, robustness
    for name, path in [('analyzer',robustness_analysis.__file__),('scorer',robustness.__file__)]:
        if report[name] != robustness_analysis.pin(path):
            raise RecoveryError('ANALYSIS_IMPLEMENTATION_DRIFT')
    root=Path(__file__).resolve().parents[1]
    for name,relative in [('measurement_replayer','training_workloads/unified_h1/robustness_measurement_replay.py'),
                          ('audit_reader','training_workloads/unified_h1/robustness_audit.py'),
                          ('force_codec','training_workloads/unified_h1/force_archive.py'),
                          ('physics_replayer','training_workloads/unified_h1/robustness_physics_replay.py'),
                          ('delivery_implementation','isaaclab-training/instinctlab/observations/robustness.py')]:
        if report.get(name)!=robustness_analysis.pin(root/relative):
            raise RecoveryError('ANALYSIS_MEASUREMENT_IMPLEMENTATION_DRIFT')
    indexed = {r['path']:r for r in inventory['files']}
    if len(indexed) != len(inventory['files']):
        raise RecoveryError('ANALYSIS_DUPLICATE_INVENTORY_PATH')
    def inventoried(pin):
        row = indexed.get(pin['path'])
        if row is None or row['sha256'] != pin['sha256'] or Path(pin['path']).stat().st_size != row['bytes']:
            raise RecoveryError('ANALYSIS_INPUT_NOT_IN_EXACT_INVENTORY')
        checked(dict(path=pin['path'],sha256=pin['sha256']))
    inventoried(auth_pin)
    seen = set()
    for pin in report['inputs']:
        if pin['path'] in seen:
            raise RecoveryError('ANALYSIS_DUPLICATE_INPUT')
        seen.add(pin['path'])
        external = [request['protocol']]
        if protocol.get('physics_replay',{}).get('mount_source'):
            external.append(protocol['physics_replay']['mount_source'])
        if {k:pin[k] for k in ('path','sha256')} in external:
            checked({k:pin[k] for k in ('path','sha256')})
        else:
            if output not in Path(pin['path']).parents:
                raise RecoveryError('ANALYSIS_OTHER_ATTEMPT_INPUT')
            inventoried(pin)
    if request['protocol']['path'] not in seen:
        raise RecoveryError('ANALYSIS_PROTOCOL_INPUT_MISSING')
    for row in report['blocks']:
        if row['replay_complete'] and any(str(output/'r6'/row['block_id']/name) not in seen
                for name in ('motion_traces.json','result.json')):
            raise RecoveryError('ANALYSIS_COMPLETE_BLOCK_WITHOUT_INPUTS')
        if row.get('measurement_replay',{}).get('bit_exact_delivery') is True and any(
                str(output/'r6'/row['block_id']/name) not in seen for name in ('measurements.bin','audit.bin')):
            raise RecoveryError('ANALYSIS_MEASUREMENT_WITHOUT_INPUTS')
        if row.get('physics_replay',{}).get('staging_reconstructed') is True and str(output/'r6'/row['block_id']/'audit.bin') not in seen:
            raise RecoveryError('ANALYSIS_PHYSICS_WITHOUT_INPUTS')
    original = report['summary']['original']
    if original['replay_complete']:
        required = [output/'evaluation_raw/r6_baseline_u640_original'/(case+'.jsonl') for case in ('Z','T','S','X','W')]
        required += [output/'r6_original_suite.json',output/'r6_original_wall_motion.json']
        if any(str(path) not in seen for path in required):
            raise RecoveryError('ANALYSIS_COMPLETE_ORIGINAL_WITHOUT_INPUTS')
    binding_path = output/'r6_model_binding.json'
    issues = []
    model_binding = None
    if str(binding_path) not in indexed:
        issues.append('MODEL_BINDING_MISSING')
    else:
        model_binding = dict(path=str(binding_path),sha256=indexed[str(binding_path)]['sha256'])
        inventoried(model_binding)
        binding = read(model_binding)
        from training_workloads.unified_h1.robustness_contract import baseline
        baseline_record = baseline(parameters)
        if (binding['checkpoint'] != baseline_record['selected_model']
                or binding['checkpoint_source_identity'] != baseline_record['source_identity']
                or binding['method_hashes'] != baseline_record['method_hashes']
                or binding['ics_clearance_margin_m'] != .15 or binding['actor_input_extension'] is not False
                or binding['physical_history_continuity_claimed'] is not False):
            raise RecoveryError('ANALYSIS_MODEL_BINDING')
    if not inventory['output_inventory_complete']:
        issues.append('INVENTORY_INCOMPLETE')
    if any(row.get('measurement_replay',{}).get('bit_exact_delivery') is not True for row in report['blocks']):
        issues.append('MEASUREMENT_REPLAY_INCOMPLETE')
    if any(row.get('physics_replay',{}).get('staging_reconstructed') is not True for row in report['blocks']):
        issues.append('PHYSICS_STAGING_REPLAY_INCOMPLETE')
    if not original['replay_complete'] or not original.get('saved_result_equal') or not original.get('saved_wall_equal') or any(
