class MemoryPath:
 def __truediv__(self,other):return self
 def exists(self):return False
class Crash(Exception):pass
class J:
 directory=MemoryPath()
 def __init__(self):self.s={'status':'MODEL_REVIEW','current_model_event':'decision-key','events':{'decision-key':{'kind':'model','receipt':None,'dispatch_claim':{'recorded':True},'process':None}}};self.crash=True
 def require_writer(self):pass
 def read(self):return copy.deepcopy(self.s)
 def observe(self,*a,**k):return {'action':'ACCEPT_RECEIPT'}
 def consume(self,key,path):self.s['events'][key].update(receipt={'path':'verified-existing-receipt','sha256':'fixture'},status='RECEIPT_RECORDED')
 def save(self,state):
  if self.crash:raise Crash('power loss after consume persisted, before phase save')
  self.s=copy.deepcopy(state)
ns={'verified_decision':lambda journal,key:{'decision':'NEEDS_REPAIR'},'RecoveryError':RuntimeError}
exec(compile(ast.Module(body=[node],type_ignores=[]),str(p),'exec'),ns)
j=J()
try:ns['model_handoff'](j,'decision-key')
except Crash as e:print(str(e))
j.crash=False
print('replay_result',ns['model_handoff'](j,'decision-key'))
