p2=pathlib.Path('tools/r6_job_handoff.py');node2=next(n for n in ast.parse(p2.read_text()).body if isinstance(n,ast.FunctionDef) and n.name=='no_model_workers')
ns2={'RecoveryError':RuntimeError};exec(compile(ast.Module(body=[node2],type_ignores=[]),str(p2),'exec'),ns2)
try:ns2['no_model_workers'](j)
except RuntimeError as e:print('subsequent_submit_gate',str(e))
